          "task": "قم بكتابة برنامج بلغة C# يجسد منطق (ما هو PRG Pattern؟)، مع إضافة التحقق من صحة المدخلات وطباعة رسائل توضيحية تدل على اكتمال المعالجة بنجاح.",
